-- Upgrade installed tracking templates without replacing credentials, custom nodes or active runs.
do $$ declare r record; g jsonb; ns jsonb; es jsonb; begin
for r in select s.tenant_id,s.value,b.id bot_id,b.graph,a.id agent_id,a.prompt from settings s join bots b on b.id=(s.value->>'bot_id')::int and b.tenant_id=s.tenant_id join agents a on a.id=(s.value->>'agent_id')::int and a.tenant_id=s.tenant_id where s.key='template:rastreamento_veicular' loop
 g:=r.graph;
 if exists(select 1 from jsonb_array_elements(g->'nodes') n where n->>'id'='setor') and exists(select 1 from jsonb_array_elements(g->'nodes') n where n->>'id'='comercial' and n->>'type'='transfer') and not exists(select 1 from jsonb_array_elements(g->'nodes') n where n->>'id'='comercial_tipo') then
 insert into settings(tenant_id,key,value) values(r.tenant_id,'template:rastreamento_veicular:before-v2',jsonb_build_object('graph',g,'prompt',r.prompt)) on conflict do nothing;
 select jsonb_agg(case when n->>'type'='choice' then jsonb_set(n,'{data}',coalesce(n->'data','{}'::jsonb)||'{"aiFallback":"on"}'::jsonb) else n end) into ns from jsonb_array_elements(g->'nodes') n;
 select coalesce(jsonb_agg(e),'[]'::jsonb) into es from jsonb_array_elements(g->'edges') e where not(e->>'from'='setor' and e->>'out' in ('o2','o3')) and not(e->>'out'='invalid' and exists(select 1 from jsonb_array_elements(g->'nodes') n where n->>'id'=e->>'from' and n->>'type'='choice'));
 g:=jsonb_set(jsonb_set(g,'{nodes}',ns||'[{"id": "comercial_tipo", "type": "choice", "data": {"text": "O atendimento Comercial é para qual tipo de pessoa?", "options": ["Pessoa Física", "Pessoa Jurídica"], "aiFallback": "on"}, "x": 860, "y": 650}, {"id": "comercial_pf", "type": "message", "data": {"text": "Comercial · Pessoa Física\nWhatsApp: +5566999776407\nhttps://wa.me/5566999776407"}, "x": 1200, "y": 650}, {"id": "comercial_pj", "type": "message", "data": {"text": "Comercial · Pessoa Jurídica\nWhatsApp: +5566996968893\nhttps://wa.me/5566996968893"}, "x": 1200, "y": 820}, {"id": "administrativo_contato", "type": "message", "data": {"text": "Administrativo\nWhatsApp: +5566999776407\nhttps://wa.me/5566999776407"}, "x": 860, "y": 1050}]'::jsonb),'{edges}',es||'[{"from": "setor", "out": "o2", "to": "comercial_tipo"}, {"from": "comercial_tipo", "out": "o0", "to": "comercial_pf"}, {"from": "comercial_pf", "out": "next", "to": "comercial"}, {"from": "comercial_tipo", "out": "o1", "to": "comercial_pj"}, {"from": "comercial_pj", "out": "next", "to": "comercial"}, {"from": "setor", "out": "o3", "to": "administrativo_contato"}, {"from": "administrativo_contato", "out": "next", "to": "administrativo"}]'::jsonb);
 update bots set graph=g where id=r.bot_id and tenant_id=r.tenant_id;
 update agents set prompt=replace(coalesce(prompt,''),'Comercial e Administrativo são compartilhados.','Comercial e Administrativo são distintos.')||E'\n\nREGRAS ATUALIZADAS DO TEMPLATE:\n'||'Você recebe clientes de uma empresa de rastreamento veicular. Use a saudação local informada pelo sistema. Apresente opções numeradas: 1. Suporte; 2. Financeiro; 3. Comercial; 4. Administrativo. Para Suporte e Financeiro, apresente 1. Ceeb Vision; 2. Link; 3. Rastreabem. Não peça para digitar nomes de empresas ou plataformas. Comercial e Administrativo são distintos. Para Comercial, apresente 1. Pessoa Física e 2. Pessoa Jurídica. Pessoa Física: +5566999776407 (https://wa.me/5566999776407). Pessoa Jurídica: +5566996968893 (https://wa.me/5566996968893). Administrativo: +5566999776407 (https://wa.me/5566999776407). Informe o contato correto; esses números não são IDs de usuários da Néxora. No Financeiro, ofereça pagamento ou atendente. Para pagamento, acione o fluxo seguro de cobrança, nunca invente boletos ou Pix. Encaminhe para a equipe exata usando os IDs das equipes fornecidos pelo sistema.' where id=r.agent_id and tenant_id=r.tenant_id;
 end if;
end loop;end $$;
